    // @item fn:tampines_steam_tables::steam_turbine_equations::converging_diverging_nozzles::choked_flow::basic_multiphase_equations::get_stagnation_conditions_from_throat_ps
#[doc = "Given throat conditions (p_t, s_t), compute the critical mass flux\nand back-calculate the stagnation conditions (p_0, h_0)\n\nThis is the inverse of the usual approach — instead of finding\nthe throat from stagnation conditions, we fix the throat and\nrecover the stagnation state.\n\nFrom energy conservation (isentropic):\nh_0 = h_t + G*² / (2 * rho_t²)\n     = h_t + v_t² * G*² / 2\n\nEntropy is conserved: s_0 = s_t\nStagnation pressure recovered via p_hs_eqm(h_0, s_0)\n\nReference: Saha (1978) NUREG/CR-0417, eq. 10\n           Moody (1975) NEDO-21052\n\nNote that this uses the homogeneous equilibrium model.\nThis was validated using Zaloudek's data"]
#[pyfunction(name = "get_stagnation_conditions_from_throat_ps")]
pub fn fn_tampines_steam_tables__steam_turbine_equations__converging_diverging_nozzles__choked_flow__basic_multiphase_equations__get_stagnation_conditions_from_throat_ps(p_t: f64, s_t: f64) -> (f64, f64, f64) { { let (e0, e1, e2) = ::tampines_steam_tables::steam_turbine_equations::converging_diverging_nozzles::choked_flow::basic_multiphase_equations::get_stagnation_conditions_from_throat_ps(from_si(p_t), from_si(s_t)); (to_si(e0), to_si(e1), to_si(e2)) } }

